function nodesAtDistance(root: TreeNode | null, target: number, k: number): number[] {
  const parent = new Map<TreeNode, TreeNode | null>();
  let start: TreeNode | null = null;
  const stack: TreeNode[] = root ? [root] : [];
  if (root) parent.set(root, null);
  while (stack.length) {
    const node = stack.pop()!;
    if (node.val === target) start = node;
    for (const child of [node.left, node.right]) {
      if (child) { parent.set(child, node); stack.push(child); }
    }
  }
  let layer: TreeNode[] = [start!];
  const seen = new Set<TreeNode>(layer);
  for (let d = 0; d < k && layer.length; d++) {
    const next: TreeNode[] = [];
    for (const node of layer) {
      for (const nb of [node.left, node.right, parent.get(node)!]) {
        if (nb && !seen.has(nb)) { seen.add(nb); next.push(nb); }
      }
    }
    layer = next;
  }
  return layer.map(n => n.val);
}

