    def nodesAtDistance(self, root: Optional[TreeNode], target: int, k: int) -> List[int]:
        parent = {root: None}
        start = None
        stack = [root]
        while stack:
            node = stack.pop()
            if node.val == target:
                start = node
            for child in (node.left, node.right):
                if child:
                    parent[child] = node
                    stack.append(child)
        layer = [start]
        seen = {start}
        for _ in range(k):
            if not layer:
                break
            nxt = []
            for node in layer:
                for nb in (node.left, node.right, parent[node]):
                    if nb and nb not in seen:
                        seen.add(nb)
                        nxt.append(nb)
            layer = nxt
        return [n.val for n in layer]

