function nodesAtDistance(root: TreeNode | null, target: number, k: number): number[] {
  const out: number[] = [];
  // add every node exactly 'left' levels below node
  const collect = (node: TreeNode | null, left: number): void => {
    if (!node || left < 0) return;
    if (left === 0) { out.push(node.val); return; }
    collect(node.left, left - 1);
    collect(node.right, left - 1);
  };
  // returns the distance from node down to the target, or -1 if the target is not below
  const find = (node: TreeNode | null): number => {
    if (!node) return -1;
    if (node.val === target) { collect(node, k); return 0; }
    const l = find(node.left);
    if (l >= 0) {
      const d = l + 1;
      if (d === k) out.push(node.val);
      else collect(node.right, k - d - 1);
      return d;
    }
    const r = find(node.right);
    if (r >= 0) {
      const d = r + 1;
      if (d === k) out.push(node.val);
      else collect(node.left, k - d - 1);
      return d;
    }
    return -1;
  };
  find(root);
  return out;
}

